"use client"

import { type CSSProperties, useEffect, useRef } from "react"
import { createRandom, round } from "../aurora/internal/random"

interface GridPatternCellsProps {
  size: number
  inset: number
  count: number
  duration: number
  seed: number
}

// The server cannot measure, so first placement assumes a typical hero and is corrected on mount.
const ASSUMED_COLUMNS = 32
const ASSUMED_ROWS = 14

/**
 * Cells flash on a CSS loop. Each time a cell's loop restarts (fully transparent) it jumps to a
 * fresh random cell, written straight to the DOM so the grid never re-renders.
 */
export const GridPatternCells = ({
  size,
  inset,
  count,
  duration,
  seed,
}: GridPatternCellsProps) => {
  const ref = useRef<SVGGElement>(null)
  const bounds = useRef({ columns: ASSUMED_COLUMNS, rows: ASSUMED_ROWS })
  const next = useRef<(() => number) | null>(null)

  const random = createRandom(seed)
  const total = Math.max(Math.round(count), 0)
  const span = Math.max(size - inset, 0)
  const cells = Array.from({ length: total }, (_, index) => {
    const column = Math.floor(random() * ASSUMED_COLUMNS)
    const row = Math.floor(random() * ASSUMED_ROWS)
    const delay = round(random() * duration * 1.5, 2)
    const length = round(duration * (0.7 + random() * 0.6), 2)
    return (
      <rect
        key={index}
        className="kg-grid-pattern__cell fill-[var(--_fill)] opacity-70"
        x={column * size + inset}
        y={row * size + inset}
        width={span}
        height={span}
        data-column={column}
        data-row={row}
        style={
          {
            animationDelay: `${delay}s`,
            animationDuration: `${length}s`,
          } as CSSProperties
        }
      />
    )
  })

  const place = (rect: SVGElement) => {
    const group = ref.current
    if (!group) return
    next.current ??= createRandom(seed + 1)
    const { columns, rows } = bounds.current
    const taken = new Set<string>()
    for (const other of Array.from(group.children) as SVGElement[]) {
      if (other !== rect) taken.add(`${other.dataset.column}:${other.dataset.row}`)
    }
    let column = 0
    let row = 0
    for (let attempt = 0; attempt < 6; attempt++) {
      column = Math.floor(next.current() * columns)
      row = Math.floor(next.current() * rows)
      if (!taken.has(`${column}:${row}`)) break
    }
    rect.dataset.column = String(column)
    rect.dataset.row = String(row)
    rect.setAttribute("x", String(column * size + inset))
    rect.setAttribute("y", String(row * size + inset))
  }

  useEffect(() => {
    const group = ref.current
    const svg = group?.ownerSVGElement
    if (!group || !svg) return
    const measure = () => {
      const { width, height } = svg.getBoundingClientRect()
      if (!width || !height) return
      const columns = Math.max(Math.floor(width / size), 1)
      const rows = Math.max(Math.floor(height / size), 1)
      bounds.current = { columns, rows }
      for (const rect of Array.from(group.children) as SVGElement[]) {
        if (
          Number(rect.dataset.column) >= columns ||
          Number(rect.dataset.row) >= rows
        ) {
          place(rect)
        }
      }
    }
    const handleIteration = (event: Event) => {
      const target = event.target as SVGElement
      if (target.classList.contains("kg-grid-pattern__cell")) place(target)
    }

    measure()
    group.addEventListener("animationiteration", handleIteration)
    const observer =
      typeof ResizeObserver === "undefined" ? null : new ResizeObserver(measure)
    observer?.observe(svg)
    return () => {
      group.removeEventListener("animationiteration", handleIteration)
      observer?.disconnect()
    }
  }, [size, inset, seed])

  return (
    <g ref={ref} className="kg-grid-pattern__cells">
      {cells}
    </g>
  )
}

/* Edge masks, the horizon tint and the flash and scroll loops do not fit in utilities. */
@layer kg.components {
  .kg-grid-pattern {
    &[data-mask="radial"] > .kg-grid-pattern__layer {
      mask-image: radial-gradient(ellipse 70% 70% at 50% 50%, #000 20%, transparent 100%);
    }

    &[data-mask="top"] > .kg-grid-pattern__layer {
      mask-image: radial-gradient(ellipse 90% 80% at 50% 0%, #000 25%, transparent 100%);
    }

    &[data-mask="bottom"] > .kg-grid-pattern__layer {
      mask-image: radial-gradient(ellipse 90% 80% at 50% 100%, #000 25%, transparent 100%);
    }

    &[data-mask="edges"] > .kg-grid-pattern__layer {
      mask-image:
        linear-gradient(to right, transparent, #000 15% 85%, transparent),
        linear-gradient(to bottom, transparent, #000 15% 85%, transparent);
      mask-composite: intersect;
    }

    /* A soft paper tint sits on the horizon line, where the floor meets the sky. */
    &[data-variant="floor"] > .kg-grid-pattern__layer::before {
      content: "";
      position: absolute;
      top: 46%;
      left: 10%;
      right: 10%;
      height: 36%;
      translate: 0 -50%;
      background: radial-gradient(ellipse 50% 50% at 50% 50%, var(--kg-paper-sky), transparent);
    }

    &[data-variant="floor"][data-animated] .kg-grid-pattern__svg {
      animation: kg-grid-pattern-scroll calc(var(--kg-grid-duration, 4s) * 0.25) linear infinite;
    }
  }

  /* The floor's SVG is one cell taller than the plane, so scrolling by one cell has no seam. */
  .kg-grid-pattern__plane {
    mask-image: linear-gradient(to bottom, transparent, #000 18%);
  }

  /* Resting opacity is the reduced-motion frame; the animation's first keyframe hides cells. */
  .kg-grid-pattern__cell {
    animation-name: kg-grid-pattern-flash;
    animation-duration: var(--kg-grid-duration, 4s);
    animation-timing-function: var(--kg-ease-in-out);
    animation-iteration-count: infinite;
    animation-fill-mode: backwards;
  }

  @media (prefers-reduced-motion: reduce) {
    .kg-grid-pattern .kg-grid-pattern__cell,
    .kg-grid-pattern .kg-grid-pattern__svg {
      animation: none;
    }
  }

  [data-kg-motion="reduce"] .kg-grid-pattern .kg-grid-pattern__cell,
  [data-kg-motion="reduce"] .kg-grid-pattern .kg-grid-pattern__svg,
  .kg-grid-pattern[data-kg-motion="reduce"] :is(.kg-grid-pattern__cell, .kg-grid-pattern__svg) {
    animation: none;
  }

  @keyframes kg-grid-pattern-flash {
    0%,
    100% {
      opacity: 0;
    }
    45% {
      opacity: 1;
    }
  }

  @keyframes kg-grid-pattern-scroll {
    to {
      transform: translate3d(0, var(--kg-grid-size, 40px), 0);
    }
  }
}

import {
  type CSSProperties,
  forwardRef,
  type HTMLAttributes,
  type ReactNode,
  useId,
} from "react"
import {
  type BackdropMask,
  backdropRoot,
  hasChildren,
  svgId,
} from "../aurora/internal/backdrop"
import { cx } from "../lib/utils/cx"
import { GridPatternCells } from "./grid-pattern-cells"

export type GridPatternMask = BackdropMask
export type GridPatternVariant = "flat" | "floor"
/** A cell to fill, as `[column, row]` counted from the top-left. */
export type GridPatternSquare = readonly [column: number, row: number]

export interface GridPatternProps extends HTMLAttributes<HTMLDivElement> {
  /** Cell size, in px. */
  size?: number
  /** Line width, in px. */
  strokeWidth?: number
  /** Any CSS color for the lines. Defaults to the foreground at low alpha. */
  stroke?: string
  /** SVG dash pattern for the lines, e.g. `"4 4"`. */
  dash?: string
  /** Cells to fill permanently. */
  squares?: readonly GridPatternSquare[]
  /** Any CSS color for filled and animated cells. Defaults to the sage paper. */
  fill?: string
  /**
   * `flat`: random cells softly light up and fade. `floor`: the grid scrolls toward the viewer.
   * Static under reduced motion.
   */
  animated?: boolean
  /** Number of cells that light up at once in animated flat mode. */
  cells?: number
  /** Seconds for one cell to light up and fade. */
  duration?: number
  /** Seeds the animated cell positions and timings. */
  seed?: number
  /** Fade the grid out toward the edges. */
  mask?: GridPatternMask
  /** `floor` lays the grid down in perspective, receding to a horizon. */
  variant?: GridPatternVariant
  /** Optional content, painted above the grid. */
  children?: ReactNode
}

/**
 * A crisp SVG line grid. The static grid ships no JavaScript; only the animated flat mode mounts
 * a small client part that moves lit cells around between flashes.
 */
export const GridPattern = forwardRef<HTMLDivElement, GridPatternProps>(
  (
    {
      size = 40,
      strokeWidth = 1,
      stroke,
      dash,
      squares,
      fill,
      animated = false,
      cells = 14,
      duration = 4,
      seed = 3,
      mask = "radial",
      variant = "flat",
      className,
      style,
      children,
      ...props
    },
    ref,
  ) => {
    const wrapper = hasChildren(children)
    const id = svgId("kg-grid", useId())
    const cell = Math.max(size, 4)
    const line = Math.max(strokeWidth, 0)
    const half = line / 2
    const floor = variant === "floor"

    const svg = (
      <svg
        className={cx(
          "kg-grid-pattern__svg absolute block",
          floor
            ? "top-[calc(var(--kg-grid-size)*-1)] left-0 h-[calc(100%+var(--kg-grid-size))]"
            : "inset-0",
        )}
        width="100%"
        height="100%"
        aria-hidden="true"
      >
        <defs>
          <pattern id={id} width={cell} height={cell} patternUnits="userSpaceOnUse">
            <path
              d={`M${cell} ${half}H${half}V${cell}`}
              fill="none"
              stroke="currentColor"
              strokeWidth={line}
              strokeDasharray={dash}
            />
          </pattern>
        </defs>
        <rect width="100%" height="100%" fill={`url(#${id})`} />
        {squares && squares.length > 0 && (
          <g className="kg-grid-pattern__squares fill-[var(--_fill)]">
            {squares.map(([column, row]) => (
              <rect
                key={`${column}:${row}`}
                x={column * cell + line}
                y={row * cell + line}
                width={Math.max(cell - line, 0)}
                height={Math.max(cell - line, 0)}
              />
            ))}
          </g>
        )}
        {animated && !floor && (
          <GridPatternCells
            size={cell}
            inset={line}
            count={cells}
            duration={duration}
            seed={seed}
          />
        )}
      </svg>
    )

    return (
      <div
        ref={ref}
        {...backdropRoot(
          "kg-grid-pattern absolute inset-0 overflow-hidden pointer-events-none data-wrapper:relative data-wrapper:inset-auto data-wrapper:overflow-visible data-wrapper:isolate data-wrapper:pointer-events-auto [--_fill:var(--kg-grid-fill,var(--kg-paper-sage))]",
          className,
          wrapper,
        )}
        data-mask={mask}
        data-variant={variant}
        data-animated={animated || undefined}
        style={
          {
            ...(stroke ? { "--kg-grid-stroke": stroke } : null),
            ...(fill ? { "--kg-grid-fill": fill } : null),
            "--kg-grid-size": `${cell}px`,
            "--kg-grid-duration": `${Math.max(duration, 0.1)}s`,
            ...style,
          } as CSSProperties
        }
        {...props}
      >
        <div
          className={cx(
            "kg-grid-pattern__layer pointer-events-none absolute inset-0 z-0 overflow-hidden",
            floor
              ? "text-[var(--kg-grid-stroke,color-mix(in_oklab,var(--kg-fg)_16%,transparent))] [perspective:260px] [perspective-origin:50%_46%]"
              : "text-[var(--kg-grid-stroke,color-mix(in_oklab,var(--kg-fg)_9%,transparent))]",
          )}
          aria-hidden="true"
        >
          {floor ? (
            <div className="kg-grid-pattern__plane absolute top-[46%] left-[-100%] h-[160%] w-[300%] origin-top [transform:rotateX(76deg)]">
              {svg}
            </div>
          ) : (
            svg
          )}
        </div>
        {wrapper && <div className="kg-grid-pattern__content relative z-1">{children}</div>}
      </div>
    )
  },
)

GridPattern.displayName = "GridPattern"
